import { NextRequest, NextResponse } from 'next/server';

// Simulate user-specific preferences that change on each request
// In a real app, this would come from a database or external service
export async function GET(request: NextRequest) {
  // Simulate dynamic data that changes on each request
  const preferences = {
    userId: Math.random().toString(36).substring(7),
    theme: Math.random() > 0.5 ? 'dark' : 'light',
    notifications: Math.random() > 0.5,
    language: ['en', 'es', 'fr', 'de'][Math.floor(Math.random() * 4)],
    lastUpdated: new Date().toISOString(),
    timestamp: Date.now(),
  };

  // Set cache headers to ensure fresh data on each request
  return NextResponse.json(preferences, {
    headers: {
      'Cache-Control': 'no-store, no-cache, must-revalidate, proxy-revalidate',
      'Pragma': 'no-cache',
      'Expires': '0',
    },
  });
}

