interface UserPreferences {
  userId: string;
  theme: 'dark' | 'light';
  notifications: boolean;
  language: string;
  lastUpdated: string;
  timestamp: number;
}

async function getUserPreferences(): Promise<UserPreferences> {
  // Fetch user preferences with cache disabled to ensure fresh data on each request
  const res = await fetch('http://localhost:3000/api/user/preferences', {
    cache: 'no-store', // Ensures data is fetched fresh on each request
  });

  if (!res.ok) {
    throw new Error('Failed to fetch user preferences');
  }

  return res.json();
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences();

  return (
    <div>
      <h2>User Dashboard</h2>
      <div style={{ marginTop: '1rem' }}>
        <h3>User Preferences</h3>
        <ul>
          <li>User ID: {preferences.userId}</li>
          <li>Theme: {preferences.theme}</li>
          <li>Notifications: {preferences.notifications ? 'Enabled' : 'Disabled'}</li>
          <li>Language: {preferences.language}</li>
          <li>Last Updated: {new Date(preferences.lastUpdated).toLocaleString()}</li>
          <li>Timestamp: {preferences.timestamp}</li>
        </ul>
        <p style={{ fontSize: '0.875rem', color: '#666', marginTop: '1rem' }}>
          Refresh the page to see updated preferences (data fetched fresh on each request)
        </p>
      </div>
    </div>
  );
}

